665	\subsection{Robust self-testing}\label{subsection:robust-self-testing}
666	
667	Now we prove a robust self-testing theorem for linear constraint system games. First, we specify precisely what we mean by robust self-testing.
668	
669	\begin{definition}[Robust self-testing for LCS games]\label{defn: robust-self-testing}
670		Let $G$ be an LCS game and $\set{\tilde A_e^{(v)}}, \set{\tilde B_e}, \ket\psi$ be a strategy presented via observables. Let $\d:\R \to \R$ be a continuous function with $\d(0) = 0$. We say that $G$ 
671		\emph{self-tests} 
672		the strategy with
673		\emph{perfect completeness}
674		and
675		\emph{$\d$-robustness}
676		if:
677		\begin{itemize}
678			\item The strategy $\set{\tilde A_e^{(v)}}, \set{\tilde B_e}, \ket\psi$ wins the game with probability $1$, and
679			\item for every strategy $\set{A_e^{(v)}}, \set{B_e}, \rho$ which wins with probability at least $1-\e$, there is a local isometry $V = V_A\otimes V_B$ and auxiliary state $\rho_{\text{aux}}$ such that for every $e,v$ with $H(e,v)\neq 0$,
680		\begin{align}
681			\label{eq:robustness-condition-state}
682			\norm{V\rho V^\dagger - \proj \psi\otimes \rho_{\text{aux}}}_1 &\leq \d(\e),\\
683			\drho{V\rho V^\dagger}{V_A A_e^{v}V_A^\dagger\otimes I_A}{(\tilde A_e^{v}\otimes I) \otimes I_B}^2 &\leq \d(\e)\text{, and}\label{eq:robustness-condition-alice}\\
684			\drho{V\rho V^\dagger}{I_A\otimes V_BB_eV_B^\dagger}{I_A\otimes (\tilde B_e\otimes I)}^2 &\leq \d(\e).\label{eq:robustness-condition-bob}
685		\end{align}
686	
687		\end{itemize}
688	\end{definition}
689	
690	
691	
692	
693	
694	We restrict our attention only to LCS games with sufficiently nice solution groups.
695	\begin{definition}\label{definition:group-test}
696		Let $\G$ be a finite solution group over $\Z_d$ and $\tau:\G \to U(\C^d)$ an irreducible representation of $\G$ with $\tau(J) = \w_dI$. We say that $\G$ \emph{group-tests $\tau$}  
697		if:
698		\begin{itemize}
699			\item every representation of $\G$ which sends $J \mapsto \w_dI$ is equivalent to $\tau$, and
700			\item every irreducible representation of $\G$ sends $J$ to $\w_d^{j}I$ for some $j\in \Z_d$.
701		\end{itemize}
702	\end{definition}
703	Our second condition may seem artificial. What we really need is the existence of some $\d$ such that if $\s$ is any irreducible not equivalent to $\tau$, then $\norm{\s(J)-\tau(J)}_2 \geq \delta$. This condition gives that to us with $\delta = \Theta(d\1)$.
704	
705	
706	\begin{theorem}\label{thm:robust-self-testing}
707		Let $G$ be an LCS game over $\Z_d$ with vertex set $V$, edge set $E$, and constraints given by  $H:V\times E \to \Z_d$ and $l: V\to \Z_d$. Let $\G$ be the solution group of $G$. Suppose that:
708		\begin{enumerate}[(i)]
709			\item \label{assumption:bounded-degree}
710			 $\abs E \leq \Delta$, $\abs V \leq \Delta$, and
711			 each equation has at most $\Delta$ variables with multiplicity, i.e.\ \mbox{$\forall v:\sum_e\abs{H(v,e)} \leq \Delta$},
712			\item \label{assumption:small-pictures}there is a canonical form $\can$ such that\footnote{We'll also need a technical assumption that for all $x\in \G$, $\can(Jx) = J\can(x)$ or $\can(Jx) = J^{1-d}\can(x)$.} 
713			every equation of the form  $\can(e)e\1 = 1$ for $e\in E$ or $\can(g)\can(gh)\1\can(h) = 1$ for $g,h\in \G$ is witnessed by a $\G$-picture in which 
714			 each variable is used at most $\Delta$ times
715			 and 
716			 each relation is used at most $\Delta$ times,
717			\item \label{assumption:w-p-irreps}
718			 $\G$ group-tests $\tau: \G \to U(\C^{d^n}) $ in the sense of Definition \ref{definition:group-test}.
719	% 		\item \label{assumption:pauli-in-image}The image of $\tau$ contains an isomorphic copy of the Pauli group $\m P_d^{\otimes n}$. 
720		\end{enumerate}
721		Then $G$ self-tests the strategy $\tilde A_e^{(v)} = \tau(e), \tilde B_e = \bar{\tau(e)}, \ket\psi = \ket{\r{EPR}_{d^n}}$
722		with perfect completeness and $O(d^2\Delta^{10}\e)$-robustness.
723	
724	\end{theorem}
725	The fact that the strategy wins the game with probability $1$ is proven as Proposition \ref{prop: perfect strategy}. The special case of $\e=0$ is the main result of \S \ref{subsection:exact-self-testing}. We remark that although the robustness bound does not seem to depend directly on $n$, typically $\Delta$ does.
726	
727	The theorem is stated for finite solution groups. Using the stability lemma from \cite{de2017operator}, almost every part of the proof goes through for amenable\footnote{A countable group is \emph{amenable} if it admits a finitely-additive translation-invariant probability measure which is defined on every subset. For a finite group $\G$, we can take this measure as the familiar $\E{x\in \G}$. More exotic examples exist among infinite groups.} groups. However, we crucially use that the length of proofs of group equations is bounded by a constant, which is not true for infinite groups. It seems plausible that this barrier can be overcome; we leave this to future work. To avoid overloading notation, we stated Theorem \ref{thm:robust-self-testing} with sub-optimal bounds. A version of it with tighter, but more notation-involved, bounds is stated and proved in the Appendix as Theorem \ref{thm:robust-self-testing-appendix}.
728	
729	
730	We break the proof into several lemmas. In the statement of each lemma, we point out which of the assumptions of the main theorem we use. Before we proceed with the proof, we fix some useful notation.  We write $\prod_{i=1}^ng_i$ for the ordered product $g_1g_2\cdots g_n$. 
731	We write $r_v$ for the relation in $\G$ corresponding to equation $v\in V$, note that this is a word in the generators, say $r_v = s_1s_2\ldots s_n$. We write $\prod_{s\in r_v}f(r_v)$ for the ordered product $f(s_1)f(s_2)\cdots f(s_n)$. 
732	For $e,e' \in E$, we say $e\sim e'$ if they share an equation, i.e.\ there is some $v$ such that $H(v,e) \neq 0 \neq H(v,e')$. Furthermore, for each edge $e$, we fix a special vertex $v_e$ such that $H(v_e,e)\neq 0$.
