 31	\subsection{Nonlocal games}
 32	
 33	\begin{definition}[Nonlocal game]
 34		For our purposes, a nonlocal game $G$ is a tuple $(A,B,X,Y,V,\pi)$, where $A,B,X,Y$ are finite sets of answers and questions for Alice and Bob, $\pi:X\times Y\to [0,1]$ is a probability distribution over questions, and $V:A\times B \times X \times Y\to \pair01$ is \emph{the win condition}. 
 35	\end{definition}
 36	
 37	\begin{definition}[Strategies for nonlocal games]
 38		If $G$ is a nonlocal game, then a strategy for $G$ is a probability distribution $p:A\times B\times X\times Y\to [0,1]$.	The \emph{value} or \emph{winning probability} of a strategy is given by 
 39		\begin{equation}
 40			\w(G;p) := \sum_{a,b,x,y}\pi(x,y)p(a,b\|x,y)V(a,b,x,y).
 41		\end{equation}
 42		If the value is equal to $1$, we say that the strategy is \emph{perfect}. If the probability distribution is separable, i.e.\ $p(a,b\|x,y) = \sum \a_i p_i(a\|x)q_i(b\|y)$ for some probability distributions $\set{p_i}, \set{q_i}$, then we say that the strategy is \emph{local}.
 43	\end{definition}
 44		%Operationally, we think of the value of a strategy as the probability that provers using the strategy win the game. 
 45		We think of a local strategy as being implemented by using only the resource of public shared randomness. Alternatively, the local strategies are the strategies which are implementable by spacelike-separated parties in a hidden variable theory of physics.
 46	\begin{definition}[Quantum strategies, projective measurement version]
 47		We say that a strategy $p:A\times B\times X\times Y\to [0,1]$ is \emph{quantum of local dimension $d$} if there exist projective measurements $\set{\set{A_x^a}_a}_x, \set{\set{B_y^b}_b}_y$ on $\C^d$ and a state $\rho \in \m L(\C^d\otimes \C^d)$ such that 
 48		\begin{equation}
 49			p(a,b\|x,y) = \Tr_\rho(A_x^a\otimes B_y^b)
 50		\end{equation}
 51		 (By \emph{projective measurement} we mean that for all $x,y,a,b$ we have $(A_x^a)^2 = A_x^a = (A_x^a)\dagg, (B_y^b)^2 = B^b_y= (B^b_y)\dagg$, and for all $x,y$, we have $\sum_a A_x^a = I = \sum_bB_y^b$.)
 52		 \\\noindent We say that a strategy is \emph{quantum} if it is quantum of local dimension $d$ for some $d$.
 53	\end{definition}
 54	We denote by $\w_*(G)$ the \emph{optimal quantum value} of $G$, i.e. the supremum over all quantum strategies of the winning probability. If the value of a strategy is $\w_*(G)$, we say that the strategy is \emph{ideal}. For quantum strategies, we use the term \emph{strategy} to refer interchangeably to the probability distribution or to the state and measurement operators producing it. 
