199	\subsection{Representation theory of finite groups}
200	
201	
202	We'll study groups through their representations. We collect here some basic facts about the representation theory of finite groups. For exposition and proofs, see e.g. \cite{dummit2004abstract}. Throughout, $G$ will be a finite group. It should be noted that some of these facts are not true of infinite groups. 
203	
204	% \begin{definition}
205	% 	Let $G$ be a group, $V$ be a $\C$-vector space, and $\m L(V)$ be the group of invertible linear transformations. A \emph{representation} of $G$ is a homomorphism $\rho: G \to \m L(V)$. The \emph{dimension} of $\rho$ is the dimension of $V$ over $\C$. 
206	% 	% $\rho$ is \emph{self-adjoint} if $\rho(g)^* = \rho(g)$ for all $g$. 
207	% 	$\rho$ is \emph{unitary} if $\rho(g)^* = \rho(g)\1$ for all $g$. 
208	% \end{definition}
209	
210	\begin{definition}
211		A $d$-dimensional \emph{representation} of $G$ is a homomorphism from $G$ to the group of invertible linear operators on $\C^d$.
212		A representation is \emph{irreducible} if it cannot be decomposed as a direct sum of two representations, each of positive dimension.
213		A representation is \emph{trivial} if its image is $\set I$, where $I$ is the identity matrix.
214		The \emph{character} of a representation $\s$ is the function defined by $g\mapsto \Tr(\s(g))$. 
215		Two representations $\rho_1$ and $\rho_2$ are \emph{equivalent} if there is a unitary $U$ such that for all $g$, $U\rho_1(g) U^\dagger = \rho_2(g)$.
216	\end{definition}
217	Notice that a $1$-dimensional representation and its character are the same function, and that $1$-dimensional representations are always irreducible. We sometimes write ``irrep'' for ``irreducible representation.'' The next fact allows us to check equivalence of representations algebraically.
218	
219	\begin{fact}
220		$\rho_1$ is equivalent to $\rho_2$ iff they have the same character. 
221	\end{fact}
222	% Implicit in the above fact is that equivalent representations have the same dimension.
223	
224	The following is immediate:
225	\begin{lemma}\label{fact:character-convex-combination}
226		Let $\s = \bigoplus_i \s_i$ be a direct sum decomposition of $\s$ into irreducibles. Let $\circ$ denote composition of maps, and let $\chi = \Tr\circ \s, \chi_i = \Tr\circ\s_i$ be the characters corresponding to the representations $\s$. Then $\chi = \sum_i \chi_i$. 
227	
228		Furthermore, define $\tilde \chi = \frac1{\dim \s}\chi$ and $\tilde\chi_i = \frac1{\dim \s_i} \chi_i$ as the \emph{normalized characters} of $\s,\s_i$. 
229		Then the normalized character of $\s$ is a convex combination of the normalized characters of $\s_i$. 
230		\begin{equation}
231			\tilde \chi = \sum_i \frac{\dim \s_i}{\dim \s}\tilde\chi_i.
232		\end{equation}
233	\end{lemma}
234	
235	There is a simple criterion to check whether a representation of a finite group is irreducible:
236	\begin{fact}\label{fact:irreducibility-criterion}
237		$\s$ is an irreducible representation of $G$ iff
238		\begin{equation}
239			\abs G = \sum_{g\in G} \Tr \s(g) \Tr\s(g\1). 
240		\end{equation}
241	\end{fact}
242	
243	\begin{definition}
244		The \emph{commutator subgroup} $[G,G]$ of $G$ is the subgroup generated by all elements of the form $[a,b] := aba\1b\1$ for $a,b\in G$. The \emph{index} $\abs{G:H}$ of a subgroup $H \leq G$ is the number of $H$-cosets in $G$. Equivalently for finite groups, the index is the quotient of the orders $\abs{G:H}= \frac{\abs G}{\abs{H}}$.
245	\end{definition}
246	
247	\begin{fact}\label{fact:1-dim-irreps}
248		$G$ has a number $\abs{G:[G,G]}$ of inequivalent $1$-dimensional irreducible representations, each of which restricts to the trivial representation on $[G,G]$.
249	\end{fact}
250	
251	\begin{fact}\label{fact:character-dimension}
252		For a finite group $G$, the size of the group is equal to the sum of the squares of the dimensions of the irreducible representations. In other words, for $R$ any set of inequivalent irreps, 
253		\begin{equation}\label{eq:character-dimension}
254				\abs G = \sum_{\s \in R} (\dim \s)^2 \text{ iff $R$ is maximal.}
255			\end{equation}	
256	\end{fact}
257	By ``maximal'', we mean that any irreducible representation is equivalent to one from $R$. This fact can be used to check whether one has a complete classification of the irreducibles of $G$. This is a special case of the following for $x = 1$.
258	\begin{fact}[Second orthogonality relation for character tables]\label{fact:orthogonality}
259		Let $x\in G$. Let $\s$ vary over a maximal set of inequivalent irreps of $G$, and let $n_\s$ be the dimension of $\s$. Then
260		\begin{equation}
261			\frac 1{\abs G}\sum_\s n_\s\Tr(\s(x)) = \delta_{x,1}.
262		\end{equation}
263	\end{fact}
264	
265	\begin{fact}[Schur's lemma]\label{fact:schur}
266		Let $\tau: G\to U(\C^d)$ be an irrep and $X \in \m L(\C^d)$ be a linear operator. Suppose that $X\tau(g) = \tau(g)X$ for all $g\in G$. Then $X = \lambda I$ is a scalar multiple of identity. 
267	\end{fact}

