 70	\begin{definition}[Self-testing]
 71	We say that a non-local game $G$ \emph{self-tests} a quantum strategy $S = (\set{\set{A_x^a}_a}_x, \set{\set{B_y^b}_b}_y, \ket{\Psi}) $ if any quantum strategy $S'$ that achieves the optimal quantum winning probability $w_*$ is equivalent up to local isometry to $S$.
 72	\end{definition}
 73	By \emph{local isometry} we mean a channel $\Phi: \m L(\m H_A\otimes \m H_B) \to \m L(\m H_A'\otimes \m H_B')$ which factors as $\Phi(\rho) = (V_A\otimes V_B) \rho(V_A\otimes V_B)^\dagger$, where $V_A: \m H_A\to \m H_A', V_B: \m H_B\to \m H_B'$ are isometries.
 74	
 75	\begin{definition}[Robustness of self-tests] We say that a non-local game $G$ is $\left(\eps,\delta(\eps)\right)$-rigid if it self-tests a strategy $S = (\set{\set{A_x^a}_a}_x, \set{\set{B_y^b}_b}_y, \ket{\Psi})$, and, moreover, for any quantum strategy $\tilde{S} = \big(\set{\set{\tilde{A}_x^{a}}_a}_x, \set{\set{\tilde{B}_y^{b}}_b}_y, \rho \big)$ that achieves a winning probability of $w_*(G) - \eps$, there exists a local isometry $\Phi$ such that 
 76	\begin{equation}
 77	\norm {\Phi(\tilde{A}_x^{a}\otimes \tilde{B}_y^{b}\ \rho \tilde{A}_x^{a}\otimes \tilde{B}_y^{b}) - \big(A_x^a\otimes B_y^b \ket{\Psi}\bra{\Psi} A_x^a\otimes B_y^b \big)\otimes \rho_{\text{extra}}}_{2} \leq \delta(\eps)
 78	\end{equation}
 79	where $\rho_{\text{extra}}$ is some auxiliary state, and $\delta(\eps)$ is a function that goes to zero with $\eps$.
 80	\end{definition}
 81	\subsection{Groups}
 82	
 83	We work with several groups via their presentations. For the basic definitions of group, quotient group, etc.\ see any abstract algebra text, e.g.\ \cite{dummit2004abstract}.
 84	\begin{definition}
 85		Let $S$ be a set of letters. We denote by $\m F(S)$ the \emph{free group on $S$}. As a set, $\m F(S)$ consists of all finite words made from $\set{s,s\1\;s\in S}$ such that no $ss\1$ or $s\1s$ appears as a substring for any $s$. The group law is given by concatenation and cancellation.
 86	\end{definition}
 87	
 88	
 89	\begin{definition}[Group presentation]
 90		Let $S$ be finite and $R$ a finite subset of $\m F(S)$. Then $G = \Braket {S:R}$ is the \emph{finitely presented group} generated by $S$ with relations from $R$. Explicitly, 
 91		$G = \m F(S)/\braket R$, where $/$ is used to denote the quotient of groups, and $\braket R$ denotes the subgroup generated by $R$. 
 92		We say that an equation $w = w'$ is \emph{witnessed by $R$} if $w'w^{-1}$ (or some cyclic permutation thereof) is a member of $R$. 
 93	\end{definition}
 94	We emphasize that in this work, we sometimes distinguish between two presentations of the same group. If $G = \braket{S:R}, G' = \braket{S':R'}$ are two finitely presented groups, we reserve equality for the case $S = S'$ and $R = R'$, and in this case we'll say $G = G'$. We'll say that $G \cong G'$ if there is a group isomorphism between them.
 95	
 96	
 97	\begin{definition}\label{definition:canonical-form}
 98		Let $G = \braket{S:R}$ be a finitely presented group and $\can: G\to \m F(S)$ be an injective function. We say that $\can$ is a \emph{canonical form} for $G$ if the induced map $\bar \can: G\to \m F(S)/\braket{R}$ is an isomorphism. In other words, we require that $\can(g)\can(h) = \can(gh)$ as elements of $G$, but not as strings.
 99	\end{definition}
