173	\begin{proof}
174		By a well-known property of the maximally entangled state, we have
175		\begin{equation}
176			\braket{ \psi | \s(e) \otimes \bar{\s(e)} | \psi} = 
177			\braket{ \psi | \s(e)\bar{\s(e)}^T \otimes I  | \psi} = 1,
178		\end{equation}
179		where $^T$ denotes the transpose. 
180		Therefore, the consistency criterion \eqref{eq:exact-win-criterion-con} is satisfied.
181		Since $\s$ is an operator solution, we have 
182		\begin{align}
183			\prod_{e} \left(A_e^{(v)}\right)^{H(v,e)} 
184			\\&= \s(\prod_e \s(e)^{H(v,e)})
185			\\&= \s(J^{l(v)}) 
186			\\&=\w_d^{l(v)}I,
187		\end{align}
188		so the constraint satisfaction criterion \eqref{eq:exact-win-criterion-sat} is satisfied.
189	\end{proof}
