845			f_A(g) = \begin{cases}
846				\w_d I, &\text{ if }g=J\\
847				A_e^{(v_e)}, &\text{ if }\can(g)=e\\
848				\prod_{s\in \can(g)} f_A(s), &\text{ otherwise,}
